   nb_id                               INTEGER     NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
   lagernummer_id                      VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Lagernummer / Lagerkomplex.',
   versandstelle_id                    VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Ort, an dem Lieferungen bearbeitet werden. Es kann sich dabei um einen physischen Ort (z.B. ein Lager oder eine_1 Gruppe_1 von Laderampen) oder um eine_1 logische Gruppierung (z.B. eine_1 Gruppe_1 von Personen, die für die Versandaktivitäten zuständig ist) handeln.',
   lagerort_id                         VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Schlüssel für die Lagerorte. Die Lagerorte sind pro Werk / Betrieb eindeutig. Aus lgort.',
   lagersortiment_id                   VARCHAR(1)       NOT NULL COLLATE 'en-ci' COMMENT 'Lagersortiment ID.',
   diff_id                             VARCHAR(1)       NOT NULL COLLATE 'en-ci' COMMENT 'Wenn eine_1 Lieferposition nicht vollständig beliefert werden kann, wird die Restmenge vom VZ nachgeliefert oder muss vom Markt neu bestellt werden. Diese Information wird auch als Nachlieferkennzeichen bezeichnet.',
   dat_lief_soll                       DATE             NOT NULL COMMENT 'Lieferdatum der Position.',
