   vertr_beleg_typ_id                  VARCHAR(4)       COLLATE 'en-ci' COMMENT 'Dieses Kennzeichen liefert die Information aus welchem Vorgang dieser Vertriebsbeleg generiert wurde, z. B. wurde der Lieferschein aufgrund eines Wareneingangs generiert.',
   art_id                              INTEGER     NOT NULL COMMENT 'Artikelnummer.',
   kunde_id                            INTEGER     NOT NULL COMMENT 'Die Kunde ID ist die wup_id des belieferten Marktes. Dazu gibt es auch eine_1 mandant_id_kunde.',
   wg_verkett_lief                     INTEGER     NOT NULL COMMENT 'Die Warengruppenverkettung gibt an, welche Artikel_1 gemeinsam auf eine_1 Palette gepackt werden.',
   menge_lief_soll_kolli               NUMBER(29,3)     COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie bezieht sich auf die Mengeneinheit der Liefermenge (LFIMG). Es handelt sich hier um Kolli!  ',
   menge_lief_ist_kolli                NUMBER(29,3)     COMMENT 'Ist-Liefermenge in Kolli.',
   menge_lief_soll_bme                 NUMBER(29,3)     COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie ist berechnet (redundante Speicherung) und in Bestellmengeneinheit dargestellt.',
   menge_lief_ist_bme                  NUMBER(29,3)     COMMENT 'Ist-Liefermenge der Lieferposition, ausgedrückt in Bestellmengeneinheit aus lfimg.',
   menge_lief_soll_pal                 NUMBER(29,3)     COMMENT 'Soll-Liefermenge in Paletten.',
   menge_lief_ist_pal                  NUMBER(29,3)     COMMENT 'Ist-Liefermenge in Paletten.',
   lief_pal_typ_id                     VARCHAR(1)       NOT NULL COLLATE 'en-ci' COMMENT 'Der Palettentyp einer Lieferung kennzeichnet, ob es sich um eine_1 Ganzpalettenlieferung, Mischpalettenlieferung, Lieferung je Markt, etc., handelt.',
   lief_pal_typ_dwh_id                 VARCHAR(2)       NOT NULL COLLATE 'en-ci' COMMENT 'Abgeleiteter Palettentyp (6 wird in 61 und 64 unterteilt),',
   mandant_id_kunde                    INTEGER     NOT NULL COMMENT 'Der Kunde kann zu einem anderen Mandanten als dem der wup_id gehören, z.B. wenn ein Lager aus CZ einen Markt in SK beliefert.',
   werbeware_id                        VARCHAR(1)       NOT NULL COLLATE 'en-ci' COMMENT 'Aus besch_lief_1: Wird gefüllt, wenn die Bestellart eine_1 Werbebestellart ist. Wertevorrat: W = Werbung, N = Normalware, B = Beides W und N, S = Schnellschuss.',
   bestellart_id                       VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Durch die Einkaufsbelegart kann man z.B. zwischen einer Bestellung, einer Anfrage und einem Lieferplan unterscheiden.',
   hu_status_id                        VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Bewegungsstatus der Handling Unit.',
   handling_unit_id_ext_parent         VARCHAR(20)      COLLATE 'en-ci' COMMENT 'Externe Handling Unit_1 Identifikation aus exidv. Nummer der Versandeinheit (NVE) PARENT.',
   handling_unit_id_ext                VARCHAR(20)      COLLATE 'en-ci' COMMENT 'Externe Handling Unit_1 Identifikation aus exidv. Nummer der Versandeinheit (NVE).',
   handling_unit_id_parent             INTEGER     COMMENT 'Übergeordnete Handling Unit.',
   originalposition_lief_fg            INTEGER     NOT NULL DEFAULT 0 COMMENT 'Kennzeichen Orginalposition.',
   position_charg_split_fg             INTEGER     COMMENT 'Position mit Chargensplit.',
   disponent_id                        VARCHAR(4)       COLLATE 'en-ci' COMMENT 'Disponent ID.',
   dat_haltbarkeit                     DATE             COMMENT 'Dieses Feld enthält das Mindesthaltbarkeitsdatum.',
   charge_id                           VARCHAR(10)      COLLATE 'en-ci' COMMENT 'Charge ID.',
   anzahl_packstueck                   INTEGER     COMMENT 'Anzahl von Packstücken.',
   vk_netto_lief_ist                   NUMBER(29,4)     COMMENT 'Ist-Liefermenge, bewertet mit dem Verkaufspreis, minus Mehrwertsteuer. Redundant abgelegt zur Performancesteigerung.',
   vk_netto_lief_soll                  NUMBER(29,4)     COMMENT 'Soll-Liefermenge, bewertet mit dem Verkaufspreis, minus Mehrwertsteuer. Redundant abgelegt zur Performancesteigerung.',
   transportsortiment_id               VARCHAR(2)       COLLATE 'en-ci' COMMENT 'Transportsortiment ID - concatenation of  Lagersortiment IDs that should be put on the same truck for transportation (for example 27 means Lagersortiment ID 2 and Lagersortiment ID 7 are transported together)',
   split_lief_kennz                    VARCHAR(1)       COMMENT 'Kennzeichen Split-Lieferung: leer = keine Splitlieferung, O = Orginalposition, S = Split-Position.',
   lief_beleg_id_orig                  INTEGER     COMMENT 'Orginal-Lieferbeleg zu Split-Lieferpositionen.',
   wg_verkett_fg                       INTEGER     NOT NULL DEFAULT 0 COMMENT 'Flag. Zeigt an, ob eine_1 Warengruppenverkettung existiert. Aus dem Feld zzlvwgrvkhier_kz.',
   wrg_id                              VARCHAR(3)       COMMENT 'Kurzbezeichnung der Währung, z.B. CZK, EUR.',
   uebg_chargensplit_pos               INTEGER     COMMENT 'Übergeordnete Position der Chargensplitposition.',
   auslieferungsgruppe_id              VARCHAR(4)       COMMENT 'Auslieferungsgruppe aus ZLF_AUSLFEL.',
   dat_erstellung                      DATE             COMMENT 'Erstellungsdatum des Lieferbeleges - Quelle: LIKP.ERDAT.',
   tms_tour_id                         INTEGER     COMMENT 'ID des Tours (Tournummer). Eine_1 Tour_1 kann an mehr als einem Datum stattfinden, daher ist die Spalte tms_tour_id allein nicht eindeutig. Aus pltop.tonr',
   dat_tour                            DATE             COMMENT 'Tourdatum',
   tms_system_id                       INTEGER     COMMENT 'Spezifiziert das Quellsystem, aus dem die Daten kommen.',
   TD_UPDATE                           TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   TD_INSERT                           TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   CONSTRAINT PK_BESCH_LIEF_WA_DET PRIMARY KEY (mandant_id, lief_beleg_id, lief_beleg_pos_id, handling_unit_id, handling_unit_pos_id, best_beleg_id) NOT ENFORCED
)  COMMENT = 'LIS-LOG - Frontend Data Mart. Warenausgangs-Positionen (Zusammenführung Lieferung + Bestellung + Handling Unit_1).';
